128	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
129	    @Override
130	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
131	        return withOwner(ownerId, owner ->
132	            new ResponseEntity<>(toOwnerDtoWithDerivedFields(owner), HttpStatus.OK));
133	    }
