135	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
136	    @Override
137	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
138	        normalizeAddress(ownerFieldsDto);
139	        rejectBlankOwnerFields(ownerFieldsDto);
140	        rejectDisposableEmailDomain(ownerFieldsDto.getEmail());
141	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
142	        rejectInvalidPostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
143	        rejectCityAtCapacity(ownerFieldsDto.getCity());
144	        rejectFutureRegistrationDate(ownerFieldsDto.getRegistrationDate());
145	        LocalDate registrationDate = businessDay(effectiveRegistrationDate(ownerFieldsDto.getRegistrationDate()));
146	        rejectDailyRegistrationLimit(registrationDate);
147	        String normalizedTelephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
148	        ownerFieldsDto.setTelephone(normalizedTelephone);
149	        String normalizedEmail = emailNormalizer.normalize(ownerFieldsDto.getEmail());
150	        ownerFieldsDto.setEmail(normalizedEmail);
151	        HttpHeaders headers = new HttpHeaders();
152	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
153	        owner.setRegistrationDate(registrationDate);
154	        owner.setCustomerCode(customerCode(owner));
155	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
156	        owner.setHouseholdId(householdId(owner));
157	        rejectDuplicateIdentity(owner);
158	        rejectHouseholdDuplicate(owner, sharesHousehold);
159	        owner.setPossibleDuplicateOf(sharesHousehold ? null : possibleDuplicateOf(owner));
160	        this.clinicService.saveOwner(owner);
161	        owner.setHouseholdSize(householdSize(owner));
162	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
163	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
164	            ownerMapper.membershipLevel(owner), ownerMapper.membershipNumber(owner));
165	        OwnerDto ownerDto = toOwnerDtoWithDerivedFields(owner);
166	        headers.setLocation(UriComponentsBuilder.newInstance()
167	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
168	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
169	    }
