260	    /**
261	     * Loads the owner with the given id and, when it exists, produces the response through
262	     * {@code action}; when no such owner exists a {@code 404 Not Found} is returned instead. The
263	     * single-owner endpoints share this "find the owner or report 404" preamble, so the lookup and
264	     * the not-found response are written in exactly one place rather than copied into each method.
265	     *
266	     * @param ownerId the id of the owner to load
267	     * @param action builds the response for an existing owner
268	     * @param <T> the response body type
269	     * @return the result of {@code action} for an existing owner, otherwise a 404 response
270	     */
271	    private <T> ResponseEntity<T> withOwner(Integer ownerId, Function<Owner, ResponseEntity<T>> action) {
272	        Owner owner = this.clinicService.findOwnerById(ownerId);
273	        if (owner == null) {
274	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
275	        }
276	        return action.apply(owner);
277	    }
278	
279	    /**
280	     * Maps a persisted owner to its {@link OwnerDto} and populates the read-only fields that are
281	     * derived from server-side state rather than stored columns (the {@code bulkSignupWarning} flag
282	     * and the {@code identityKey}). Both the create endpoint and the single-owner read endpoint
283	     * return their owner through this method, so an owner is decorated identically on either path
284	     * and each derived field is computed in exactly one place.
285	     *
286	     * @param owner the persisted owner to represent
287	     * @return the owner DTO with its derived read-only fields populated
288	     */
289	    private OwnerDto toOwnerDtoWithDerivedFields(Owner owner) {
290	        owner.setHouseholdSize(householdSize(owner));
291	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
292	        ownerDto.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
293	        ownerDto.setIdentityKey(identityKey(owner));
294	        Integer possibleDuplicateOf = owner.getPossibleDuplicateOf();
295	        ownerDto.setPossibleDuplicate(possibleDuplicateOf != null);
296	        ownerDto.setPossibleDuplicateOf(possibleDuplicateOf);
297	        return ownerDto;
298	    }
299	
300	    /**
301	     * Canonicalizes the submitted address in place before it is validated, stored and returned, so
302	     * every later step - the required-field check, the persisted value and the response - sees the
303	     * single normalized form produced by {@link AddressNormalizer#normalize(String)} (see that method
304	     * for the trim/collapse/upper-case/abbreviation rules). Normalizing once here, at the head of the
305	     * create flow, keeps address canonicalization in exactly one place rather than spread across the
306	     * steps that read the address.
307	     *
308	     * <p>An address may be supplied either as the structured {@code addressLine1} (with an optional
309	     * {@code addressLine2}) or as the single flat {@code address}, the latter kept for backward
310	     * compatibility. Whichever address fields are supplied are normalized, and the structured fields
311	     * are preferred when present: the flat {@code address} returned is composed as the normalized
312	     * {@code addressLine1}, with a single space and the normalized {@code addressLine2} appended when an
313	     * {@code addressLine2} is present; only when no {@code addressLine1} is supplied does the flat
314	     * {@code address} retain its own normalized value.
315	     *
316	     * @param ownerFieldsDto the submitted owner fields, whose address fields are replaced with their normalized form
317	     */
318	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
319	        String addressLine1 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
320	        String addressLine2 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
321	        String flatAddress = addressNormalizer.normalize(ownerFieldsDto.getAddress());
322	        ownerFieldsDto.setAddressLine1(addressLine1);
323	        ownerFieldsDto.setAddressLine2(addressLine2);
324	        if (addressLine1 != null && !addressLine1.isBlank()) {
325	            String composed = addressLine2 != null && !addressLine2.isBlank()
326	                ? addressLine1 + " " + addressLine2
327	                : addressLine1;
328	            ownerFieldsDto.setAddress(composed);
329	        } else {
330	            ownerFieldsDto.setAddress(flatAddress);
331	        }
332	    }
333	
334	    /**
335	     * Rejects an owner whose required text fields are blank (whitespace-only). Missing (null)
336	     * and empty fields are already rejected by Bean Validation on {@link OwnerFieldsDto}; this
337	     * closes the gap for {@code address} and {@code city}, whose values may be non-empty yet
338	     * blank (e.g. {@code "   "}). The offending field names are reported through an
339	     * {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice} renders
340	     * as a 400 response carrying an {@code errors} array of field names.
341	     *
342	     * @param ownerFieldsDto the submitted owner fields
343	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
344	     */
345	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
346	        List<String> blankFields = new ArrayList<>();
347	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
348	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
349	        addRequiredAddress(blankFields, ownerFieldsDto);
350	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
351	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
352	        if (!blankFields.isEmpty()) {
353	            throw new InvalidOwnerFieldsException(blankFields);
354	        }
355	    }
356	
357	    private void addIfBlank(List<String> blankFields, String field, String value) {
358	        if (value != null && value.isBlank()) {
359	            blankFields.add(field);
360	        }
361	    }
362	
363	    /**
364	     * Records the address requirement's offending field name(s) into {@code blankFields}. An owner
365	     * must supply an address in EITHER accepted form: the structured {@code addressLine1} or the flat
366	     * {@code address} (kept for backward compatibility). The requirement is satisfied when at least one
367	     * of those is present and non-blank; only when both are missing or blank is {@code address} reported
368	     * as the offending field. Holding the "an owner must have an address" rule in its own method - rather
369	     * than a bare entry in the field list - gives it one place to live as the accepted address forms grow.
370	     *
371	     * @param blankFields the accumulating list of blank required-field names
372	     * @param ownerFieldsDto the submitted owner fields
373	     */
374	    private void addRequiredAddress(List<String> blankFields, OwnerFieldsDto ownerFieldsDto) {
375	        if (isBlank(ownerFieldsDto.getAddressLine1()) && isBlank(ownerFieldsDto.getAddress())) {
376	            blankFields.add("address");
377	        }
378	    }
379	
380	    private boolean isBlank(String value) {
381	        return value == null || value.isBlank();
382	    }
383	
384	    /**
385	     * Rejects an owner whose {@code email} domain is on the disposable-domain blocklist
386	     * ({@code mailinator.com}, {@code tempmail.com}, {@code guerrillamail.com}). Email is validated
387	     * only when present, so an owner created without one is accepted unchanged; syntactic validity is
388	     * already enforced by Bean Validation's {@code @Email} constraint on {@link OwnerFieldsDto}, so
389	     * this only rejects an otherwise well-formed address that uses a throwaway provider (see
390	     * {@link DisposableEmailDomains#isDisposable(String)} for the case-insensitive domain match). A
391	     * blocklisted address is reported through a {@link DisposableEmailDomainException}, which the
392	     * {@code ExceptionControllerAdvice} renders as a 400 response naming the {@code email} field.
393	     *
394	     * @param email the supplied email, or {@code null} when omitted
395	     * @throws DisposableEmailDomainException if the email's domain is blocklisted
396	     */
397	    private void rejectDisposableEmailDomain(String email) {
398	        if (disposableEmailDomains.isDisposable(email)) {
399	            throw new DisposableEmailDomainException(email);
400	        }
401	    }
402	
403	    /**
404	     * Validates the owner's optional {@code postcode} against its {@code city} region. Postcode is
405	     * validated only when present, so an owner created without one is accepted unchanged. A supplied
406	     * postcode is already constrained to four digits by Bean Validation on {@link OwnerFieldsDto}; this
407	     * additionally rejects a well-formed postcode that is out of range for the city's region using the
408	     * shared {@link Region#acceptsPostcode(int) region-to-postcode} table ({@code NSW 2000-2099},
409	     * {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known region accepts any 4-digit
410	     * postcode. An out-of-range postcode is reported through an {@link InvalidOwnerPostcodeException},
411	     * which the {@code ExceptionControllerAdvice} renders as a 400 response.
412	     *
413	     * @param city the city of the owner being created
414	     * @param postcode the supplied postcode, or {@code null} when omitted
415	     * @throws InvalidOwnerPostcodeException if the postcode is out of range for the city's region
416	     */
417	    private void rejectInvalidPostcode(String city, String postcode) {
418	        if (postcode == null || postcode.isBlank()) {
419	            return;
420	        }
421	        Region.forCity(city).ifPresent(region -> {
422	            if (!region.acceptsPostcode(Integer.parseInt(postcode))) {
423	                throw new InvalidOwnerPostcodeException(postcode, city);
424	            }
425	        });
426	    }
427	
428	    /**
429	     * Number of leading hex characters of the identity hash retained as the {@code HASH8} segment of
430	     * the {@code customerCode}.
431	     */
432	    private static final int CUSTOMER_CODE_HASH_LENGTH = 8;
433	
434	    /**
435	     * Builds the {@code customerCode} assigned to a newly created owner, formatted
436	     * {@code '<REGION>-<HASH8>'}: {@code REGION} is the owner's canonical region code resolved from
437	     * its {@code postcode} (falling back to its {@code city}) through the shared
438	     * {@link Region#code(String, String)}, and {@code HASH8} is the first 8 upper-case hex characters
439	     * of the SHA-256 digest of the owner's normalized telephone followed by its last name
440	     * (e.g. {@code 'NSW-1A2B3C4D'}). When this base code collides with an existing owner's
441	     * {@code customerCode}, {@code '-<n>'} is appended with the smallest {@code n} of 2 or more that
442	     * makes the result unique (e.g. {@code 'NSW-1A2B3C4D-2'}), so distinct owners always receive
443	     * distinct customer codes.
444	     *
445	     * @param owner the owner being created, with its telephone already normalized
446	     * @return the formatted, de-duplicated customer code
447	     */
448	    private String customerCode(Owner owner) {
449	        String region = Region.code(owner.getPostcode(), owner.getCity());
450	        String hash8 = hashPrefix(owner.getTelephone() + owner.getLastName(), CUSTOMER_CODE_HASH_LENGTH);
451	        String base = region + "-" + hash8;
452	        return deduplicateCustomerCode(base);
453	    }
454	
455	    /**
456	     * Ensures the given base {@code customerCode} does not collide with an existing owner's
457	     * {@code customerCode}. When no existing owner carries the base code it is returned unchanged;
458	     * otherwise {@code '-<n>'} is appended with the smallest {@code n} of 2 or more that yields a code
459	     * held by no existing owner.
460	     *
461	     * @param base the computed base customer code, formatted {@code '<REGION>-<HASH8>'}
462	     * @return the base code, or a {@code '<base>-<n>'} variant that is unique among existing owners
463	     */
464	    private String deduplicateCustomerCode(String base) {
465	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
466	            .map(Owner::getCustomerCode)
467	            .filter(java.util.Objects::nonNull)
468	            .collect(java.util.stream.Collectors.toSet());
469	        if (!existing.contains(base)) {
470	            return base;
471	        }
472	        int n = 2;
473	        while (existing.contains(base + "-" + n)) {
474	            n++;
475	        }
476	        return base + "-" + n;
477	    }
478	
479	    /**
480	     * Counts how many existing owners already share the given {@code firstName} and {@code lastName},
481	     * compared case-insensitively (using {@link java.util.Locale#ROOT}-independent
482	     * {@link String#equalsIgnoreCase(String)}). The count reflects the owners present before the
483	     * current create, so a name that is unique on create yields {@code 0}. The value is stored on the
484	     * new owner and surfaced as the read-only {@code namesakeCount} field.
485	     *
486	     * @param firstName the first name of the owner being created
487	     * @param lastName the last name of the owner being created
488	     * @return the number of existing owners with the same first and last name (case-insensitive)
489	     */
490	    private int namesakeCount(String firstName, String lastName) {
491	        return (int) countOwners(owner -> equalsIgnoreCase(owner.getFirstName(), firstName)
492	            && equalsIgnoreCase(owner.getLastName(), lastName));
493	    }
494	
495	    private boolean equalsIgnoreCase(String a, String b) {
496	        return a == null ? b == null : a.equalsIgnoreCase(b);
497	    }
498	
499	    /**
500	     * The maximum number of owners a single city may contain. Once a city already holds this many
501	     * owners, further owners in that city are rejected by {@link #rejectCityAtCapacity(String)}.
502	     */
503	    private static final long MAX_OWNERS_PER_CITY = 50L;
504	
505	    /**
506	     * Rejects a create request whose city already contains {@link #MAX_OWNERS_PER_CITY} or more
507	     * owners. Existing owners are matched to the requested city case-insensitively (using
508	     * {@link java.util.Locale#ROOT}-independent {@link String#equalsIgnoreCase(String)}), mirroring
509	     * the per-city counting used for the customer code. A city at capacity is reported through an
510	     * {@link OwnerCityAtCapacityException}, which the {@code ExceptionControllerAdvice} renders as a
511	     * 409 Conflict response.
512	     *
513	     * @param city the city of the owner being created
514	     * @throws OwnerCityAtCapacityException if the city already holds the maximum number of owners
515	     */
516	    private void rejectCityAtCapacity(String city) {
517	        if (ownersInCity(city) >= MAX_OWNERS_PER_CITY) {
518	            throw new OwnerCityAtCapacityException(city);
519	        }
520	    }
521	
522	    /**
523	     * Counts the existing owners whose {@code city} matches the given city, compared
524	     * case-insensitively (see {@link #equalsIgnoreCase(String, String)}). Used by the per-city
525	     * capacity check ({@link #rejectCityAtCapacity(String)}) to count a city's owners.
526	     *
527	     * @param city the city to count owners for
528	     * @return the number of existing owners in that city
529	     */
530	    private long ownersInCity(String city) {
531	        return countOwners(owner -> equalsIgnoreCase(owner.getCity(), city));
532	    }
533	
534	    /**
535	     * The maximum number of owners that may be registered on a single day. Once this many owners
536	     * already carry a given {@code registrationDate}, further owners for that date are rejected by
537	     * {@link #rejectDailyRegistrationLimit(LocalDate)}.
538	     */
539	    private static final long MAX_OWNERS_PER_DAY = 100L;
540	
541	    /**
542	     * Resolves the effective registration date for a create request: the value supplied in the
543	     * request when present, otherwise the server's current date. The result is the raw effective
544	     * date before the business-day adjustment applied by {@link #businessDay(LocalDate)}.
545	     *
546	     * @param suppliedDate the registration date from the request, or {@code null} when omitted
547	     * @return the supplied date, or today when none was supplied
548	     */
549	    private LocalDate effectiveRegistrationDate(LocalDate suppliedDate) {
550	        return suppliedDate != null ? suppliedDate : LocalDate.now();
551	    }
552	
553	    /**
554	     * Rejects a create request whose supplied {@code registrationDate} lies after the server's
555	     * current date. A registration date may be supplied to backdate a create - and is defaulted to
556	     * today when omitted - but it may never be in the future. The check is applied to the raw
557	     * supplied value before the business-day adjustment ({@link #businessDay(LocalDate)}), so a
558	     * future date is rejected regardless of how that adjustment would move it. A future date is
559	     * reported through a {@link FutureRegistrationDateException}, which the
560	     * {@code ExceptionControllerAdvice} renders as a 400 Bad Request response naming the
561	     * {@code registrationDate} field.
562	     *
563	     * @param suppliedDate the registration date from the request, or {@code null} when omitted
564	     * @throws FutureRegistrationDateException if the supplied date is later than the server date
565	     */
566	    private void rejectFutureRegistrationDate(LocalDate suppliedDate) {
567	        if (suppliedDate != null && suppliedDate.isAfter(LocalDate.now())) {
568	            throw new FutureRegistrationDateException(suppliedDate);
569	        }
570	    }
571	
572	    /**
573	     * The fixed list of public holidays that are not business days. A registration date that lands
574	     * on one of these is rolled forward by {@link #businessDay(LocalDate)} to the next non-holiday
575	     * business day, exactly as it is rolled forward off a weekend.
576	     */
577	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
578	        LocalDate.of(2026, 1, 1),
579	        LocalDate.of(2026, 1, 26),
580	        LocalDate.of(2026, 4, 25),
581	        LocalDate.of(2026, 12, 25),
582	        LocalDate.of(2026, 12, 28));
583	
584	    /**
585	     * Adjusts a date so it falls on a business day, rolling forward off weekends and public
586	     * holidays. A Saturday, Sunday or {@link #PUBLIC_HOLIDAYS listed public holiday} is rolled
587	     * forward one day at a time until the first non-holiday weekday is reached; any other weekday is
588	     * returned unchanged. Applied to the effective registration date so that a weekend or holiday
589	     * value - whether supplied in the request or defaulted to the server date - is stored as the
590	     * next business day, and every value derived from the registration date (such as the membership
591	     * number's year segment and the daily create-limit bucket) uses the adjusted business day.
592	     *
593	     * @param date the effective registration date
594	     * @return the same date when it is a non-holiday weekday, otherwise the next business day
595	     */
596	    private LocalDate businessDay(LocalDate date) {
597	        while (isNonBusinessDay(date)) {
598	            date = date.plusDays(1);
599	        }
600	        return date;
601	    }
602	
603	    /**
604	     * Whether the given date is a weekend day or a listed public holiday, and so not a business day.
605	     *
606	     * @param date the date to test
607	     * @return {@code true} for a Saturday, Sunday or {@link #PUBLIC_HOLIDAYS listed public holiday}
608	     */
609	    private boolean isNonBusinessDay(LocalDate date) {
610	        DayOfWeek dayOfWeek = date.getDayOfWeek();
611	        return dayOfWeek == DayOfWeek.SATURDAY
612	            || dayOfWeek == DayOfWeek.SUNDAY
613	            || PUBLIC_HOLIDAYS.contains(date);
614	    }
615	
616	    /**
617	     * Rejects a create request once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
618	     * created on the given day, counted by {@code registrationDate}. A day at capacity is reported
619	     * through a {@link DailyOwnerRegistrationLimitException}, which the {@code ExceptionControllerAdvice}
620	     * renders as a 429 Too Many Requests response.
621	     *
622	     * @param date the registration date of the owner being created (today)
623	     * @throws DailyOwnerRegistrationLimitException if the day already holds the maximum number of owners
624	     */
625	    private void rejectDailyRegistrationLimit(LocalDate date) {
626	        if (ownersRegisteredOn(date) >= MAX_OWNERS_PER_DAY) {
627	            throw new DailyOwnerRegistrationLimitException(date);
628	        }
629	    }
630	
631	    /**
632	     * Counts the existing owners whose {@code registrationDate} equals the given day. Shared by the
633	     * hard daily create limit ({@link #rejectDailyRegistrationLimit(LocalDate)}) and the soft
634	     * {@code bulkSignupWarning} flag ({@link #bulkSignupWarning(LocalDate)}) so both accumulate a
635	     * day's owners identically.
636	     *
637	     * @param date the registration date to count owners for
638	     * @return the number of existing owners registered on that day
639	     */
640	    private long ownersRegisteredOn(LocalDate date) {
641	        return countOwners(owner -> date.equals(owner.getRegistrationDate()));
642	    }
643	
644	    /**
645	     * The soft daily create threshold above which the read-only {@code bulkSignupWarning} flag is
646	     * raised. Once more than this many owners share a {@code registrationDate}, that day is flagged
647	     * as unusually high volume - a warning well below the hard {@link #MAX_OWNERS_PER_DAY} cap.
648	     */
649	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
650	
651	    /**
652	     * Derives the read-only {@code bulkSignupWarning} flag for an owner: {@code true} when more than
653	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have been created (counted by
654	     * {@code registrationDate}) on the given day, otherwise {@code false}. Uses the same per-day
655	     * accumulation as {@link #rejectDailyRegistrationLimit(LocalDate)}. A {@code null} date (an owner
656	     * without a registration date, such as seed data) is never flagged.
657	     *
658	     * @param date the owner's registration date (the day it was created), or {@code null}
659	     * @return {@code true} if the day already holds more than the warning threshold of owners
660	     */
661	    private boolean bulkSignupWarning(LocalDate date) {
662	        if (date == null) {
663	            return false;
664	        }
665	        return ownersRegisteredOn(date) > BULK_SIGNUP_WARNING_THRESHOLD;
666	    }
667	
668	    /**
669	     * Rejects a create request whose derived {@code identityKey} exactly equals an existing owner's.
670	     * The identity key consolidates the former separate telephone, email and household duplicate
671	     * checks into a single value: {@code normalizedTelephone + '|' + (email or empty) + '|' +
672	     * (householdId or empty)} (see {@link #identityKey(Owner)}). Because the telephone is part of the
673	     * key, two members of the same household (same {@code householdId}) with different telephones have
674	     * different identity keys and are both allowed; only an exact full-key match is a duplicate. A
675	     * collision is reported through a {@link DuplicateOwnerIdentityException}, which the
676	     * {@code ExceptionControllerAdvice} renders as a 409 Conflict response.
677	     *
678	     * @param owner the fully-populated owner being created (telephone, email and household id set)
679	     * @throws DuplicateOwnerIdentityException if an existing owner has the same identity key
680	     */
681	    private void rejectDuplicateIdentity(Owner owner) {
682	        String key = identityKey(owner);
683	        boolean duplicate = existingOwnerMatches(this::identityKey, key);
684	        if (duplicate) {
685	            throw new DuplicateOwnerIdentityException(key);
686	        }
687	    }
688	
689	    /**
690	     * Rejects a create request that would join an existing household unless it declares the shared
691	     * household with {@code sharesHousehold}. The household is keyed on {@code (lastName, postcode)}
692	     * through the deterministic {@link #householdId(Owner)}, so any existing owner with the same last
693	     * name and postcode is a member of the same household. A second such owner is a household
694	     * duplicate and is rejected with a 409 (via {@link DuplicateOwnerIdentityException}); setting
695	     * {@code sharesHousehold} bypasses this block, so the owner is created as a declared household
696	     * member instead. Owners without a {@code householdId} (e.g. no postcode) have no household to
697	     * collide with and are always allowed.
698	     *
699	     * @param owner the fully-populated owner being created (household id set)
700	     * @param sharesHousehold whether the request declared it shares an existing household
701	     * @throws DuplicateOwnerIdentityException if the household already exists and was not declared
702	     */
703	    private void rejectHouseholdDuplicate(Owner owner, boolean sharesHousehold) {
704	        if (sharesHousehold) {
705	            return;
706	        }
707	        String household = owner.getHouseholdId();
708	        if (household == null) {
709	            return;
710	        }
711	        if (existingOwnerMatches(this::householdId, household)) {
712	            throw new DuplicateOwnerIdentityException(identityKey(owner));
713	        }
714	    }
715	
716	    /**
717	     * Computes the soft-match {@code possibleDuplicateOf} for a newly created owner: the id of the
718	     * first existing owner that shares this owner's {@code lastName} (compared case-insensitively) and
719	     * {@code postcode} while carrying a <em>different</em> telephone (compared by canonical E.164 form,
720	     * see {@link TelephoneNormalizer#canonicalize(String)}), or {@code null} when no such owner exists.
721	     * The check runs only after the exact-identity duplicate check ({@link #rejectDuplicateIdentity(Owner)})
722	     * has passed, so a shared last-name-and-postcode with the same telephone has already been rejected as
723	     * a hard duplicate and can never surface here. A blank {@code postcode} never matches, since two
724	     * owners without a postcode do not share one. The captured id is stored on the new owner and surfaced
725	     * as the read-only {@code possibleDuplicate} / {@code possibleDuplicateOf} fields.
726	     *
727	     * @param owner the fully-populated owner being created (telephone normalized)
728	     * @return the id of the first soft-matching existing owner, or {@code null} when none matches
729	     */
730	    private Integer possibleDuplicateOf(Owner owner) {
731	        if (owner.getPostcode() == null || owner.getPostcode().isBlank()) {
732	            return null;
733	        }
734	        String telephone = telephoneNormalizer.canonicalize(owner.getTelephone());
735	        return this.clinicService.findAllOwners().stream()
736	            .filter(existing -> equalsIgnoreCase(existing.getLastName(), owner.getLastName())
737	                && owner.getPostcode().equals(existing.getPostcode())
738	                && !java.util.Objects.equals(telephone, telephoneNormalizer.canonicalize(existing.getTelephone())))
739	            .map(Owner::getId)
740	            .filter(java.util.Objects::nonNull)
741	            .findFirst()
742	            .orElse(null);
743	    }
744	
745	    /**
746	     * Reduces an owner to its derived {@code identityKey}, formatted
747	     * {@code '<normalizedTelephone>|<email>|<householdId>'}: the owner's telephone reduced to its
748	     * canonical E.164 form (see {@link TelephoneNormalizer#canonicalize(String)}), the owner's
749	     * normalized (lower-cased) email or the empty string when absent (see
750	     * {@link EmailNormalizer#normalize(String)}), and the owner's {@code householdId} or the empty
751	     * string when absent, joined by {@code '|'}. Two owners are duplicates exactly when their whole
752	     * identity keys are equal. The key never contains {@code null} segments, so the create endpoint's
753	     * single duplicate check compares this one value across owners.
754	     *
755	     * @param owner the owner to derive the identity key for
756	     * @return the owner's identity key
757	     */
758	    private String identityKey(Owner owner) {
759	        String telephone = telephoneNormalizer.canonicalize(owner.getTelephone());
760	        String normalizedEmail = emailNormalizer.normalize(owner.getEmail());
761	        String email = normalizedEmail == null ? "" : normalizedEmail;
762	        String household = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
763	        return telephone + "|" + email + "|" + household;
764	    }
765	
766	    /**
767	     * Finds the first existing owner that already carries the given comparison {@code key}, derived
768	     * from each owner by {@code keyExtractor}. Owners for which the extractor yields {@code null} are
769	     * ignored (a {@code null} key never equals the sought key). The create endpoint's duplicate
770	     * checks reduce both an existing owner and the owner being created to the same canonical key;
771	     * this returns the matched existing owner itself, so a caller can either reject the collision or
772	     * record which owner was matched. Owners flagged deleted (soft-deleted) are excluded, so a
773	     * collision with only a deleted owner is not reported and the create is allowed.
774	     *
775	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
776	     * @param key the canonical key of the owner being created
777	     * @return the first existing owner sharing the key, or empty when none does
778	     */
779	    private Optional<Owner> findExistingOwner(Function<Owner, String> keyExtractor, String key) {
780	        return this.clinicService.findAllOwners().stream()
781	            .filter(owner -> !owner.isDeleted())
782	            .filter(owner -> key.equals(keyExtractor.apply(owner)))
783	            .findFirst();
784	    }
785	
786	    /**
787	     * Reports whether any existing owner already carries the given comparison {@code key}, derived
788	     * from each owner by {@code keyExtractor} (see {@link #findExistingOwner(Function, String)}).
789	     * The create endpoint's duplicate checks use this to reduce both an existing owner and the owner
790	     * being created to the same canonical key and reject a match.
791	     *
792	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
793	     * @param key the canonical key of the owner being created
794	     * @return {@code true} if some existing owner shares the key
795	     */
796	    private boolean existingOwnerMatches(Function<Owner, String> keyExtractor, String key) {
797	        return findExistingOwner(keyExtractor, key).isPresent();
798	    }
799	
800	    /**
801	     * Counts the existing owners that satisfy the given {@code predicate}. The create endpoint's
802	     * count-based rules - the per-city capacity, the per-day create limit and the derived
803	     * {@code namesakeCount} - all accumulate owners over {@link ClinicService#findAllOwners()} and
804	     * differ only in the predicate they count by, so the scan-and-count is written in exactly one
805	     * place and each rule supplies just its own predicate.
806	     *
807	     * @param predicate the condition an owner must satisfy to be counted
808	     * @return the number of existing owners that satisfy the predicate
809	     */
810	    private long countOwners(Predicate<Owner> predicate) {
811	        return this.clinicService.findAllOwners().stream()
812	            .filter(predicate)
813	            .count();
814	    }
815	
816	    /**
817	     * Delimiter joining the canonical {@code lastName} and the {@code postcode} when deriving the
818	     * shared {@code householdId}.
819	     */
820	    private static final String HOUSEHOLD_KEY_DELIMITER = "|";
821	
822	    /**
823	     * Reduces the household {@code lastName} to a canonical form for case-insensitive,
824	     * whitespace-insensitive comparison: leading and trailing whitespace is trimmed, every run of
825	     * internal whitespace is collapsed to a single space, and the result is lower-cased using
826	     * {@link java.util.Locale#ROOT} so comparison is locale-independent.
827	     *
828	     * @param value the raw field value, or {@code null}
829	     * @return the canonical value, or {@code null} when {@code value} is {@code null}
830	     */
831	    private String canonicalizeHousehold(String value) {
832	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
833	    }
834	
835	    /**
836	     * Derives the deterministic, shared {@code householdId} for an owner from its {@code lastName}
837	     * and {@code postcode}. The identifier is the first 12 upper-case hex characters of the SHA-256
838	     * hash of {@code normalizedLastName + '|' + postcode} (see {@link #canonicalizeHousehold(String)}
839	     * for the last-name normalization), so every owner with the same last name and postcode -
840	     * regardless of casing or spacing - is automatically assigned the identical value. Owners without
841	     * a postcode have no household basis and are given no household id ({@code null}).
842	     *
843	     * @param owner the owner being created
844	     * @return the shared household identifier, or {@code null} when the owner has no postcode
845	     */
846	    /**
847	     * Counts the owners in the given owner's household: the existing owners that share its
848	     * {@code householdId} (see {@link #householdId(Owner)}), which - because the owner being counted is
849	     * itself persisted before it is decorated - includes the owner. An owner with no {@code householdId}
850	     * (e.g. no postcode) has no shared household and counts as a household of one. The value feeds the
851	     * household factor of the owner's membership points.
852	     *
853	     * @param owner the owner whose household size is being derived
854	     * @return the number of owners in the owner's household (at least {@code 1})
855	     */
856	    private int householdSize(Owner owner) {
857	        String household = owner.getHouseholdId();
858	        if (household == null) {
859	            return 1;
860	        }
861	        return (int) countOwners(existing -> household.equals(existing.getHouseholdId()));
862	    }
863	
864	    private String householdId(Owner owner) {
865	        String postcode = owner.getPostcode();
866	        if (postcode == null || postcode.isBlank()) {
867	            return null;
868	        }
869	        String key = canonicalizeHousehold(owner.getLastName()) + HOUSEHOLD_KEY_DELIMITER + postcode;
870	        return hashPrefix(key, HOUSEHOLD_ID_LENGTH);
871	    }
872	
873	    /**
874	     * Number of leading hex characters of the household hash retained as the shared
875	     * {@code householdId}.
876	     */
877	    private static final int HOUSEHOLD_ID_LENGTH = 12;
878	
879	    /**
880	     * Computes the leading {@code length} upper-case hex characters of the SHA-256 digest of the
881	     * UTF-8 bytes of {@code input}. This is the shared hashing primitive behind the derived
882	     * identifiers that fingerprint owner fields - such as the household-scoped {@code householdId} -
883	     * so every such identifier is produced by the same algorithm and differs only in the value it
884	     * hashes and the number of hex characters it keeps.
885	     *
886	     * @param input the value to hash
887	     * @param length the number of leading hex characters to keep
888	     * @return the leading {@code length} upper-case hex characters of the SHA-256 digest
889	     */
890	    private String hashPrefix(String input, int length) {
891	        try {
892	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
893	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
894	            StringBuilder sb = new StringBuilder(digest.length * 2);
895	            for (byte b : digest) {
896	                sb.append(String.format("%02X", b));
897	            }
898	            return sb.substring(0, length);
899	        } catch (java.security.NoSuchAlgorithmException e) {
900	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
901	        }
902	    }
903	}
